// == Virtual BMS :: CONFIG =====================================================
// Edit to match YOUR pack, then redeploy. Fires once on start.
// Per-cell volts assume LiFePO4. Change cellCount for your series count.
const cfg = {
  cellCount: 16,            // series cells (16S~48V, 8S~24V, 4S~12V)

  // setpoints (per cell, V)
  cellSyncV:        3.55,   // cells at/above this  => treat as full
  cellBalanceDelta: 0.08,   // OR (max-min) at/below this => balanced
  cellProtectV:     3.60,   // begin folding charge back above this (max cell)
  cellMaxV:         3.65,   // software ceiling: CCL->0, CVL clamped here
  cellFloatV:       3.375,  // per-cell float

  // currents (A)
  chargeMax:     100,       // normal charge-current limit (CCL)
  chargeHoldMin:   5,       // CCL floor kept during float
  dischargeMax:  200,       // discharge-current limit (DCL)

  // timers (ms)
  watchdogMs:       20000,  // no fresh cell data for this long => SAFE mode
  absorbHoldMaxMs:  7200000,// cap balance hold at 2h, then float anyway

  // SAFE-mode fallback (your hardware charge limits are the REAL backstop)
  safeCellV:     3.45,
  safeChargeMax:   20
};
flow.set('cfg', cfg);
flow.set('cvlAbsorb', +(cfg.cellSyncV  * cfg.cellCount).toFixed(2));
flow.set('cvlFloat',  +(cfg.cellFloatV * cfg.cellCount).toFixed(2));
flow.set('cvlCeil',   +(cfg.cellMaxV   * cfg.cellCount).toFixed(2));
flow.set('cvlSafe',   +(cfg.safeCellV  * cfg.cellCount).toFixed(2));
flow.set('stage', 'BULK');
node.status({fill:'blue', shape:'dot', text:'config loaded :: ' + cfg.cellCount + 'S'});
return null;

// == Virtual BMS :: CONTROLLER (state machine + fold-back + watchdog) =========
// Runs on the 2s tick. Emits the virtual-battery property object on output 1.
// Two-phase: (1) settle the charge stage, (2) derive CVL/CCL from that stage.
// SAFE is an OUTPUT overlay on stale/missing data; it never erases the stage.
const cfg = flow.get('cfg');
if (!cfg){ node.status({fill:'grey',shape:'ring',text:'no config yet'}); return null; }

const now   = Date.now();
const stale = (now - (flow.get('lastCellUpdate') || 0)) > cfg.watchdogMs;
const EPS   = 1e-6;                              // float-compare tolerance

const maxCell = flow.get('maxCell');
const minCell = flow.get('minCell');
const packV   = flow.get('packV');
const packI   = flow.get('packI');
const soc     = flow.get('soc');

const cvlAbsorb = flow.get('cvlAbsorb');
const cvlFloat  = flow.get('cvlFloat');
const cvlCeil   = flow.get('cvlCeil');
const cvlSafe   = flow.get('cvlSafe');

let stage = flow.get('stage') || 'BULK';         // persisted charge FSM state
let cvl, ccl, dcl = cfg.dischargeMax, hiCell = 0, imbal = 0, note = '', mode = stage;

function r1(x){ return Math.round(x*10)/10; }
function r2(x){ return Math.round(x*100)/100; }
function r3(x){ return Math.round(x*1000)/1000; }

function publish(){
  flow.set('stage', stage);                      // persist FSM (not the SAFE overlay)
  const payload = {
    "Info/MaxChargeVoltage":    r2(cvl),
    "Info/MaxChargeCurrent":    r1(Math.max(0, ccl)),
    "Info/MaxDischargeCurrent": r1(dcl),
    "Alarms/HighCellVoltage":   hiCell,
    "Alarms/CellImbalance":     imbal
  };
  if (packV   != null) payload["Dc/0/Voltage"]          = r2(packV);
  if (packI   != null) payload["Dc/0/Current"]          = r1(packI);
  if (soc     != null) payload["Soc"]                   = r1(soc);
  if (maxCell != null) payload["System/MaxCellVoltage"] = maxCell;
  if (minCell != null) payload["System/MinCellVoltage"] = minCell;
  const delta = (maxCell != null && minCell != null) ? r3(maxCell - minCell) : null;
  const dec = {mode:mode, stage:stage, cvl:payload["Info/MaxChargeVoltage"],
               ccl:payload["Info/MaxChargeCurrent"], dcl:payload["Info/MaxDischargeCurrent"],
               maxCell:maxCell, minCell:minCell, delta:delta, soc:soc, note:note};
  flow.set('decision', dec);
  const col = (mode === 'SAFE') ? 'red' : (mode === 'FLOAT' ? 'green' : 'yellow');
  node.status({fill:col, shape:'dot',
    text: mode + ' cvl' + dec.cvl + ' ccl' + dec.ccl +
          (delta != null ? ' d' + delta : '') + (note ? ' :: ' + note : '')});
  return {payload:payload, decision:dec, connected:true};
}

// -- SAFE overlay: stale / missing cell data (hardware limits are the backstop)
if (stale || maxCell == null || minCell == null){
  mode = 'SAFE'; cvl = cvlSafe; ccl = cfg.safeChargeMax; note = 'stale/absent cell data';
  return publish();                              // leaves flow('stage') untouched
}

const delta  = maxCell - minCell;
const synced = (minCell >= cfg.cellSyncV - EPS) || (delta <= cfg.cellBalanceDelta + EPS);

if (maxCell >= cfg.cellProtectV - EPS)        hiCell = 1;
if (maxCell >= cfg.cellMaxV - EPS)            hiCell = 2;
if (delta   >  cfg.cellBalanceDelta*1.5 + EPS) imbal = 1;

// -- phase 1: FSM transitions (BULK -> ABSORB[+balance hold] -> FLOAT), chained
if (stage === 'BULK' &&
    (maxCell >= cfg.cellSyncV - EPS || (packV != null && packV >= cvlAbsorb - EPS))){
  stage = 'ABSORB'; flow.set('absorbStart', now);
}
if (stage === 'ABSORB'){
  const held = now - (flow.get('absorbStart') || now);
  if (synced){ stage = 'FLOAT'; note = 'cells synced'; }
  else if (held > cfg.absorbHoldMaxMs){ stage = 'FLOAT'; note = 'hold timeout'; }
}
if (stage === 'FLOAT' &&
    maxCell < cfg.cellFloatV - 0.03 && (soc == null || soc < 95)){
  stage = 'BULK';
}
mode = stage;

// -- phase 2: setpoints from the settled stage -------------------------------
if (stage === 'FLOAT'){ cvl = cvlFloat;  ccl = cfg.chargeHoldMin; }
else                  { cvl = cvlAbsorb; ccl = cfg.chargeMax; }   // BULK & ABSORB

// -- high-cell fold-back overlay (trims CCL/CVL as the top cell climbs) -------
if (maxCell > cfg.cellProtectV + EPS){
  const span = Math.max(1e-4, cfg.cellMaxV - cfg.cellProtectV);
  const frac = Math.min(1, (maxCell - cfg.cellProtectV) / span);  // 0..1
  ccl = Math.max(0, Math.min(ccl, cfg.chargeMax * (1 - frac)));
  cvl = Math.min(cvl, cvlCeil);
  if (!note) note = 'fold-back ' + Math.round(frac*100) + '%';
}

cvl = Math.max(cvl, cvlFloat);     // never command below float
return publish();

// Publish Victron MQTT keep-alive so dbus values keep streaming.
// portalId is learned from the first N/<portal>/... message the ingest sees.
const portal = flow.get('portalId');
if (!portal) return null;
msg.topic = 'R/' + portal + '/keepalive';
msg.payload = '';
return msg;

// == Virtual BMS :: INGEST (Victron battery service on dbus/MQTT) =============
// Wired from mqtt-in nodes on N/+/battery/+/...  Updates flow context only;
// the Controller tick does the maths.
function val(p){ return (p && typeof p === 'object' && 'value' in p) ? p.value : p; }
const t = msg.topic || '';
const parts = t.split('/');
if (parts[0] === 'N' && parts.length > 2) flow.set('portalId', parts[1]); // for keep-alive
const raw = val(msg.payload);
if (raw === null || raw === undefined || isNaN(Number(raw))) return null;
const n = Number(raw);
if      (t.endsWith('/System/MaxCellVoltage')) flow.set('maxCell', n);
else if (t.endsWith('/System/MinCellVoltage')) flow.set('minCell', n);
else if (t.endsWith('/Dc/0/Voltage'))          flow.set('packV',  n);
else if (t.endsWith('/Dc/0/Current'))          flow.set('packI',  n);
else if (t.endsWith('/Soc'))                   flow.set('soc',    n);
flow.set('lastCellUpdate', Date.now());
return null;
